/// <summary>
/// Stages data into the temporary table.
/// </summary>
/// <param name = "_stagingLaneMap">Staging lane map.</param>
/// <returns>METFulfilmentStagingLaneTmp record.</returns>
public static METFulfilmentStagingLaneTmp stageData(Map _stagingLaneMap)
{
    METFulfilmentStagingLaneTmp stagingLaneTmp,
                                stagingLaneGrpTmp;
    SalesId                     salesId;
    CustAccount                 custAccount;
    MapEnumerator               mapEnum;
    METNumberOfCustomers        noOfCust;

    mapEnum = _stagingLaneMap.getEnumerator() as MapEnumerator;

    while (mapEnum && mapEnum.moveNext())
    {
        ttsbegin;

        [salesId, custAccount] = mapEnum.currentKey();
        noOfCust = mapEnum.currentValue();

        stagingLaneTmp.clear();
        stagingLaneTmp.SalesId = salesId;
        stagingLaneTmp.CustAccount = custAccount;

        stagingLaneTmp.insert();

        ttscommit;
    }

    //Note: There may be a case where multiple sales orders have same customer.
    //Sum is needed on the basis of customer not on the basis of sales order.
    insert_recordset stagingLaneGrpTmp (SalesId, NumberOfCustomers)
        select salesId, sum(NumberOfCustomers) from stagingLaneTmp
            group by stagingLaneTmp.SalesId;

    //Note: int2str is not allowed during insert and update record set.
    //This change is made in consideration that an update in inMemory table in loop traversal will
    //be less costly.
    while select forupdate stagingLaneGrpTmp
    {
        ttsbegin;
        stagingLaneGrpTmp.StagingLaneId = int2Str(stagingLaneGrpTmp.NumberOfCustomers);
        stagingLaneGrpTmp.update();
        ttscommit;
    }

    return stagingLaneGrpTmp;
}
